#!/usr/bin/env python3
"""Incremental Kotlin/Jetpack Compose migration from verified Agenda Clara 2.4.0."""
import base64,zlib
from pathlib import Path
base=Path("AgendaClara");app=base/"app";src=app/"src/main/java/pe/agendaclara/app"
def replace(file,old,new):
    s=file.read_text(encoding="utf-8")
    if s.count(old)!=1:raise RuntimeError("2.5 anchor mismatch in "+str(file)+": "+repr(old[:80]))
    file.write_text(s.replace(old,new,1),encoding="utf-8")
root=base/"build.gradle"
replace(root,"    id 'com.android.application' version '8.13.2' apply false","    id 'com.android.application' version '8.13.2' apply false\n    id 'org.jetbrains.kotlin.android' version '2.4.10' apply false\n    id 'org.jetbrains.kotlin.plugin.compose' version '2.4.10' apply false")
gradle=app/"build.gradle"
replace(gradle,"plugins { id 'com.android.application' }","plugins { id 'com.android.application'; id 'org.jetbrains.kotlin.android'; id 'org.jetbrains.kotlin.plugin.compose' }")
replace(gradle,"        versionCode 13\n        versionName '2.4.0'","        versionCode 14\n        versionName '2.5.0'")
replace(gradle,"    packaging { jniLibs { useLegacyPackaging = true } }","    packaging { jniLibs { useLegacyPackaging = true } }\n    buildFeatures { compose true }\n    kotlinOptions { jvmTarget = '1.8' }")
with gradle.open("a",encoding="utf-8") as f:f.write("""
dependencies {
    implementation platform('androidx.compose:compose-bom:2026.02.00')
    implementation 'androidx.compose.ui:ui'
    implementation 'androidx.compose.foundation:foundation'
    implementation 'androidx.compose.material3:material3'
    implementation 'androidx.activity:activity-compose:1.10.1'
}
""")
manifest=app/"src/main/AndroidManifest.xml"
replace(manifest,'        <activity android:name=".MainActivity" android:exported="true"','        <activity android:name=".ComposeDayActivity" android:exported="false" android:theme="@style/AppTheme" android:windowSoftInputMode="adjustResize" />\n        <activity android:name=".MainActivity" android:exported="true"')
main=src/"MainActivity.java"
replace(main,'    void tasksPage(){\n        List<Task> all=Store.get(this).all();','    void tasksPage(){\n        LinearLayout modern=card(body);modern.setBackground(gradient(0xffedf3ff,0xffffffff,20));modern.addView(text("Vista moderna · Kotlin + Compose",16,INK,true));modern.addView(text("Consulta pendientes con búsqueda y filtros. Edita con el editor existente, sin cambiar tus datos.",12,MUTED,false));gap(modern,6);modern.addView(primaryButton("Abrir vista diaria moderna  →",()->startActivity(new Intent(this,ComposeDayActivity.class))));\n        List<Task> all=Store.get(this).all();')
compressed="";
(src/"ComposeDayActivity.kt").write_bytes(zlib.decompress(base64.b64decode(compressed)))
print("AGENDA_2_5_APPLIED: incremental Compose activity; existing native flows kept.")
